// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL, LogFile} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function testFuzz_property(uint256 amount) public {
        // Deploy a log file and initialize c (required setup: Log must have code).
        LogFile log = new LogFile();
        c.SetLogFile(address(log));
        c.SetMinSum(0);
        c.Initialized();

        // Use the test contract itself as the adversarial (reverting) caller.
        // Its receive() reverts, so the outgoing Ether transfer in Collect fails.
        amount = bound(amount, 0, 1e30);
        vm.deal(address(this), amount);
        c.Deposit{value: amount}();

        uint256 beforeBal = c.balances(address(this));

        // The deciding call: the external transfer to this contract reverts.
        try c.Collect(amount) {
            // If Collect succeeds on the reference, the balance must have been deducted
            // (transfer succeeded). On the mutant it always succeeds.
            assertTrue(c.balances(address(this)) == beforeBal - amount);
        } catch {
            // The reference reverts when the transfer fails; the balance must be unchanged.
            assertTrue(c.balances(address(this)) == beforeBal);
        }

        // The single general assertion: since the transfer to this contract always fails,
        // the reference never decreases the caller's balance.
        assertTrue(c.balances(address(this)) == beforeBal);
    }

    receive() external payable {
        revert();
    }
}
